/* Ai livelli superiori: l'italiano se c'e', se no l'originale. */
function spellHigherIt(sp){
  if (!sp) return '';
  if (sp.source === 'custom' || sp.homebrew) return sp.higher || '';
  return (SPELLS_HIGHER_IT[sp.id] || sp.higher || '');
}
/* Componenti materiali: l'italiano se c'e', se no l'originale. */
function spellMatIt(sp){
  if (!sp) return '';
  if (sp.source === 'custom' || sp.homebrew) return sp.mat || '';
  return (SPELLS_MAT_IT[sp.id] || sp.mat || '');
}
